            String text = in.nextLine().trim();
            if (text.equals("q")) { System.out.println("Bye"); break; }
            try {
                int count = Integer.parseInt(text);
                if (count < 0 || count > 1000) { System.out.println("Invalid"); continue; }
                System.out.println("Accepted: " + count);
